export default function Animation({ progress }) {
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const lerp = (a, b, t) => a + (b - a) * t;
  const smoothstep = (a, b, t) => {
    const x = clamp((t - a) / (b - a));
    return x * x * (3 - 2 * x);
  };

  const p = clamp(progress || 0, 0, 1);

  // Geometry plan: zoom-in/cutaway anatomy, center-out reading around the heart
  const boardPlan = {
    composition: "zoom-in/cutaway",
    readingPath: [
      { x: 92, y: 70, note: "Title" },
      { x: 94, y: 138, note: "Four chambers claim" },
      { x: 520, y: 310, note: "Heart cutaway + septum" },
      { x: 770, y: 150, note: "Oxygenated path note + red arrows" },
      { x: 160, y: 470, note: "One-way valves note" },
      { x: 140, y: 420, note: "Blue path arrows + vena cavae" },
      { x: 520, y: 506, note: "Return: septum prevents mixing" }
    ],
    reservedRegions: [
      // Title strip (must be within x=54..946,y=30..104)
      { name: "title", x: 78, y: 52, w: 0.62 * 40 * 20, h: 1.35 * 40 }, // "Human cardiac anatomy"

      // Text lines (content region only x=64..936,y=122..500)
      { name: "t_fourChambers", x: 86, y: 132, w: 0.62 * 28 * 13, h: 1.35 * 28 }, // "Four chambers"
      { name: "t_oxy", x: 664, y: 132, w: 0.62 * 24 * 22, h: 1.35 * 24 }, // "Oxygenated: lungs →"
      { name: "t_valves", x: 86, y: 468, w: 0.62 * 24 * 20, h: 1.35 * 24 }, // "One-way flow: valves"
      { name: "t_deoxy", x: 86, y: 418, w: 0.62 * 24 * 22, h: 1.35 * 24 }, // "Deoxygenated: body →"
      { name: "t_septum", x: 360, y: 508, w: 0.62 * 22 * 15, h: 1.35 * 22 }, // "Septum separates"

      // Diagram cluster (heart + vessels) inside content bounds
      { name: "diagram_heart", x: 272, y: 132, w: 468, h: 356 },

      // Label lanes around silhouette (kept outside)
      { name: "labels_left", x: 80, y: 160, w: 180, h: 300 },
      { name: "labels_right", x: 754, y: 160, w: 182, h: 300 },
      { name: "labels_top", x: 320, y: 122, w: 360, h: 84 },

      // Later annotation region (below heart but still within safe content area for leader)
      { name: "annotate_septum", x: 340, y: 494, w: 320, h: 50 }
    ]
  };

  // Colors / style
  const paper = "#fbfbf8";
  const ink = "#1f2937";
  const softInk = "#374151";
  const frame = "#d1d5db";
  const red = "#be185d"; // oxygenated
  const blue = "#3b82f6"; // deoxygenated
  const teal = "#14b8a6";
  const amber = "#d97706";
  const green = "#65a30d";

  const font =
    "Chalkboard SE, Marker Felt, Bradley Hand, Comic Sans MS, Trebuchet MS, sans-serif";

  // Heart placement
  const hx = 520,
    hy = 312;

  // Two meaningful motions driven by progress:
  // 1) blood cells moving along each flow path
  // 2) valve leaflets opening/closing slightly as "valves" are discussed
  const oxyT = smoothstep(0.52, 0.96, p);
  const deoxyT = smoothstep(0.66, 0.98, p);
  const valvePulse = 0.35 * smoothstep(0.38, 0.78, p) * (0.65 + 0.35 * Math.sin(10 * Math.PI * p));
  const valveGap = 5 + 10 * valvePulse;

  // Piecewise linear point along polyline
  const pointOn = (pts, t) => {
    const n = pts.length / 2;
    if (n < 2) return { x: pts[0] || 0, y: pts[1] || 0 };
    let total = 0;
    const Ls = [];
    for (let i = 0; i < n - 1; i++) {
      const x1 = pts[i * 2],
        y1 = pts[i * 2 + 1];
      const x2 = pts[(i + 1) * 2],
        y2 = pts[(i + 1) * 2 + 1];
      const L = Math.hypot(x2 - x1, y2 - y1);
      Ls.push(L);
      total += L;
    }
    let d = t * total;
    for (let i = 0; i < n - 1; i++) {
      const L = Ls[i];
      if (d <= L || i === n - 2) {
        const u = L === 0 ? 0 : d / L;
        const x1 = pts[i * 2],
          y1 = pts[i * 2 + 1];
        const x2 = pts[(i + 1) * 2],
          y2 = pts[(i + 1) * 2 + 1];
        return { x: lerp(x1, x2, u), y: lerp(y1, y2, u) };
      }
      d -= L;
    }
    return { x: pts[(n - 1) * 2], y: pts[(n - 1) * 2 + 1] };
  };

  // Flow paths (kept anatomically plausible for a cutaway schematic)
  // Oxygenated: pulmonary veins -> LA -> mitral -> LV -> aortic valve -> aorta
  const oxyPts = [
    740, 214, // pulmonary veins in (right side of page)
    668, 238, // into LA
    632, 270, // toward mitral
    624, 324, // into LV
    650, 372, // toward outflow tract
    690, 318, // up to aortic root
    708, 220 // aorta up
  ];

  // Deoxygenated: SVC/IVC -> RA -> tricuspid -> RV -> pulmonary valve -> pulmonary artery
  const deoxyPts = [
    364, 170, // SVC down
    404, 230, // into RA
    420, 280, // toward tricuspid
    430, 344, // into RV
    468, 366, // toward pulmonary valve
    492, 304, // up to PA root
    430, 214 // pulmonary artery toward lungs
  ];

  const oxyDot = pointOn(oxyPts, oxyT);
  const deoxyDot = pointOn(deoxyPts, deoxyT);

  // Heart silhouette and internal walls (more "full scene" with layered fills)
  const heartOuter =
    `M ${hx - 115} ${hy - 120}
     C ${hx - 170} ${hy - 60}, ${hx - 160} ${hy + 40}, ${hx - 105} ${hy + 110}
     C ${hx - 70} ${hy + 155}, ${hx - 10} ${hy + 170}, ${hx + 35} ${hy + 135}
     C ${hx + 70} ${hy + 108}, ${hx + 110} ${hy + 60}, ${hx + 135} ${hy + 10}
     C ${hx + 165} ${hy - 55}, ${hx + 145} ${hy - 120}, ${hx + 80} ${hy - 150}
     C ${hx + 30} ${hy - 172}, ${hx - 35} ${hy - 168}, ${hx - 75} ${hy - 142}
     C ${hx - 92} ${hy - 132}, ${hx - 104} ${hy - 126}, ${hx - 115} ${hy - 120} Z`;

  const heartInnerCavity =
    `M ${hx - 92} ${hy - 92}
     C ${hx - 130} ${hy - 40}, ${hx - 122} ${hy + 30}, ${hx - 84} ${hy + 92}
     C ${hx - 62} ${hy + 128}, ${hx - 14} ${hy + 136}, ${hx + 22} ${hy + 112}
     C ${hx + 58} ${hy + 88}, ${hx + 98} ${hy + 48}, ${hx + 110} ${hy + 10}
     C ${hx + 126} ${hy - 44}, ${hx + 112} ${hy - 92}, ${hx + 68} ${hy - 112}
     C ${hx + 30} ${hy - 128}, ${hx - 42} ${hy - 126}, ${hx - 92} ${hy - 92} Z`;

  // Septum curve (divider)
