     C ${hx - 12} ${hy - 40}, ${hx - 10} ${hy + 10}, ${hx + 6} ${hy + 68}
     C ${hx + 18} ${hy + 110}, ${hx + 18} ${hy + 132}, ${hx + 8} ${hy + 150}`;

  // Vessel shapes (simple but volumetric)
  const aortaOuter =
    `M ${hx + 94} ${hy - 148}
     C ${hx + 132} ${hy - 158}, ${hx + 158} ${hy - 130}, ${hx + 150} ${hy - 98}
     C ${hx + 142} ${hy - 66}, ${hx + 108} ${hy - 46}, ${hx + 80} ${hy - 60}
     C ${hx + 56} ${hy - 72}, ${hx + 58} ${hy - 138}, ${hx + 94} ${hy - 148} Z`;

  const aortaTube = `M ${hx + 108} ${hy - 152} C ${hx + 150} ${hy - 160}, ${hx + 176} ${hy - 126}, ${hx + 166} ${hy - 86}
                     C ${hx + 156} ${hy - 48}, ${hx + 116} ${hy - 30}, ${hx + 80} ${hy - 52}`;

  const paOuter =
    `M ${hx - 70} ${hy - 136}
     C ${hx - 110} ${hy - 144}, ${hx - 142} ${hy - 116}, ${hx - 134} ${hy - 84}
     C ${hx - 126} ${hy - 52}, ${hx - 94} ${hy - 40}, ${hx - 64} ${hy - 56}
     C ${hx - 38} ${hy - 70}, ${hx - 34} ${hy - 124}, ${hx - 70} ${hy - 136} Z`;

  const paTube = `M ${hx - 84} ${hy - 140} C ${hx - 128} ${hy - 148}, ${hx - 164} ${hy - 114}, ${hx - 154} ${hy - 74}
                  C ${hx - 144} ${hy - 34}, ${hx - 104} ${hy - 24}, ${hx - 64} ${hy - 48}`;

  // Vena cavae (blue tone)
  const svcPath = `M ${hx - 172} ${hy - 138} C ${hx - 168} ${hy - 92}, ${hx - 160} ${hy - 40}, ${hx - 140} ${hy - 6}
                   C ${hx - 122} ${hy + 22}, ${hx - 104} ${hy + 30}, ${hx - 92} ${hy + 26}`;
  const ivcPath = `M ${hx - 132} ${hy + 176} C ${hx - 130} ${hy + 138}, ${hx - 126} ${hy + 106}, ${hx - 112} ${hy + 80}
                   C ${hx - 96} ${hy + 48}, ${hx - 90} ${hy + 34}, ${hx - 92} ${hy + 26}`;

  // Pulmonary veins (red tone) entering LA
  const pv1 = `M ${hx + 220} ${hy - 92} C ${hx + 190} ${hy - 82}, ${hx + 166} ${hy - 68}, ${hx + 136} ${hy - 56}`;
  const pv2 = `M ${hx + 224} ${hy - 52} C ${hx + 194} ${hy - 48}, ${hx + 170} ${hy - 40}, ${hx + 140} ${hy - 34}`;

  // Valve leaflet helpers (schematic, but placed at correct junctions)
  const mitralX = hx + 34,
    mitralY = hy + 6;
  const tricuspidX = hx - 38,
    tricuspidY = hy + 14;
  const aorticX = hx + 64,
    aorticY = hy - 60;
  const pulmonaryX = hx - 26,
    pulmonaryY = hy - 62;

  const leaflet = (x, y, dir = 1, color = amber) => (
    <g>
      <path
        d={`M ${x} ${y}
            C ${x + dir * (10 + valveGap)} ${y - 10}, ${x + dir * (22 + valveGap)} ${y + 6}, ${x + dir * (8 + valveGap)} ${y + 18}
            C ${x + dir * 2} ${y + 22}, ${x - dir * 6} ${y + 10}, ${x} ${y} Z`}
        fill={color}
        opacity="0.9"
        stroke={ink}
        strokeWidth="1.6"
        strokeLinejoin="round"
      />
      <path
        d={`M ${x + dir * 4} ${y + 2} C ${x + dir * (12 + valveGap)} ${y + 2}, ${x + dir * (14 + valveGap)} ${y + 10}, ${x + dir * 6} ${y + 14}`}
        fill="none"
        stroke="#fff7ed"
        strokeWidth="1.6"
        opacity="0.8"
        strokeLinecap="round"
      />
    </g>
  );

  // Arrowhead oriented roughly by last segment direction
  const arrowHead = (x, y, dx, dy, color) => {
    const L = Math.hypot(dx, dy) || 1;
    const ux = dx / L,
      uy = dy / L;
    const px = -uy,
      py = ux;
    const s = 10;
    return (
      <polygon
        points={`${x},${y} ${x - ux * s - px * 6},${y - uy * s - py * 6} ${x - ux * s + px * 6},${y - uy * s + py * 6}`}
        fill={color}
        opacity="0.9"
      />
    );
  };

  // End directions for arrowheads
  const oxyDx = oxyPts[oxyPts.length - 2] - oxyPts[oxyPts.length - 4];
  const oxyDy = oxyPts[oxyPts.length - 1] - oxyPts[oxyPts.length - 3];
  const deoxyDx = deoxyPts[deoxyPts.length - 2] - deoxyPts[deoxyPts.length - 4];
  const deoxyDy = deoxyPts[deoxyPts.length - 1] - deoxyPts[deoxyPts.length - 3];

  return (
    <svg viewBox="0 0 1000 560" xmlns="http://www.w3.org/2000/svg">
