      <rect x="0" y="0" width="1000" height="560" fill={paper} />
      <rect x="54" y="54" width="892" height="452" fill="none" stroke={frame} strokeWidth="2" />
      <rect x="64" y="122" width="872" height="378" fill="none" stroke="#e5e7eb" strokeWidth="1" opacity="0.55" />

      {/* Title */}
      <text
        x="78"
        y="84"
        fontFamily={font}
        fontSize="40"
        fill={ink}
        data-teach-order={1}
        data-teach-kind="write"
        data-teach-weight={10}
        data-teach-sentence={0}
      >
        Human cardiac anatomy
      </text>

      {/* Sentence [1]: first claim */}
      <text
        x="86"
        y="154"
        fontFamily={font}
        fontSize="28"
        fill={softInk}
        data-teach-order={2}
        data-teach-kind="write"
        data-teach-weight={8}
        data-teach-sentence={1}
      >
        Four chambers
      </text>

      {/* Sentence [1]: heart cutaway (fuller scene with layered tissue + cavities) */}
      <g data-teach-order={3} data-teach-kind="diagram" data-teach-weight={10} data-teach-sentence={1}>
        {/* Outer myocardium */}
        <path d={heartOuter} fill="#f3c6c6" stroke={ink} strokeWidth="3" strokeLinejoin="round" />
        {/* Shaded right edge */}
        <path
          d={`M ${hx + 38} ${hy - 150}
              C ${hx + 112} ${hy - 134}, ${hx + 152} ${hy - 70}, ${hx + 136} ${hy + 10}
              C ${hx + 118} ${hy + 96}, ${hx + 60} ${hy + 144}, ${hx + 10} ${hy + 156}
              C ${hx + 58} ${hy + 120}, ${hx + 82} ${hy + 74}, ${hx + 92} ${hy + 24}
              C ${hx + 102} ${hy - 26}, ${hx + 84} ${hy - 102}, ${hx + 38} ${hy - 150} Z`}
          fill="#eaa7a7"
          opacity="0.95"
        />
        {/* Inner cavity region */}
        <path d={heartInnerCavity} fill="#f7e1e1" opacity="0.9" stroke="#b91c1c" strokeWidth="1.2" />
        {/* Septum (thicker divider) */}
        <path d={septumPath} fill="none" stroke="#9ca3af" strokeWidth="8" strokeLinecap="round" opacity="0.9" />
        <path d={septumPath} fill="none" stroke={ink} strokeWidth="2.2" strokeLinecap="round" opacity="0.75" />

        {/* Chamber cavities (subtle tint differences) */}
        <path
          d={`M ${hx - 86} ${hy - 70}
              C ${hx - 116} ${hy - 34}, ${hx - 112} ${hy + 16}, ${hx - 78} ${hy + 54}
              C ${hx - 56} ${hy + 78}, ${hx - 18} ${hy + 80}, ${hx - 6} ${hy + 54}
              C ${hx - 18} ${hy + 10}, ${hx - 36} ${hy - 38}, ${hx - 86} ${hy - 70} Z`}
          fill="#dbeafe"
