        />
        <path
          d={`M ${hx + 10} ${hy - 70}
              C ${hx + 0} ${hy - 30}, ${hx + 12} ${hy + 6}, ${hx + 36} ${hy + 36}
              C ${hx + 56} ${hy + 62}, ${hx + 96} ${hy + 62}, ${hx + 98} ${hy + 26}
