        {/* Papillary muscles + chordae (adds real cutaway detail) */}
        <g>
          <ellipse cx={hx - 44} cy={hy + 116} rx="16" ry="10" fill="#93c5fd" opacity="0.65" stroke={ink} strokeWidth="1.2" />
          <ellipse cx={hx + 74} cy={hy + 124} rx="18" ry="11" fill="#fda4af" opacity="0.55" stroke={ink} strokeWidth="1.2" />
