          <line x1={aorticX} y1={aorticY - 2} x2="742" y2="360" stroke={ink} strokeWidth="2" />
          <text
            x="770"
            y="364"
            fontFamily={font}
            fontSize="20"
            fill={amber}
            data-teach-order={12}
            data-teach-kind="label"
            data-teach-weight={7}
            data-teach-sentence={2}
          >
            Aortic valve
          </text>
        </g>
      </g>

      {/* Sentence [3]: oxygenated path note + vessel labels + red flow arrows */}
      <text
        x="664"
        y="154"
        fontFamily={font}
        fontSize="24"
        fill={red}
        data-teach-order={13}
        data-teach-kind="write"
        data-teach-weight={7}
        data-teach-sentence={3}
      >
        Oxygenated: lungs →
      </text>

      <g data-teach-order={14} data-teach-kind="label" data-teach-weight={7} data-teach-sentence={3}>
        {/* Aorta label */}
        <line x1={hx + 150} y1={hy - 120} x2="742" y2="180" stroke={ink} strokeWidth="2" />
        <text
          x="770"
          y="184"
          fontFamily={font}
          fontSize="20"
          fill={ink}
          data-teach-order={14}
          data-teach-kind="label"
          data-teach-weight={7}
          data-teach-sentence={3}
        >
          Aorta
        </text>

        {/* Pulmonary veins label */}
        <line x1={hx + 150} y1={hy - 70} x2="742" y2="400" stroke={ink} strokeWidth="2" />
        <text
          x="770"
          y="404"
          fontFamily={font}
          fontSize="20"
          fill={ink}
          data-teach-order={15}
          data-teach-kind="label"
          data-teach-weight={7}
          data-teach-sentence={3}
        >
          Pulmonary veins
        </text>
      </g>

      <g data-teach-order={16} data-teach-kind="arrow" data-teach-weight={9} data-teach-sentence={3}>
        <polyline
          points={oxyPts.join(" ")}
          fill="none"
          stroke={red}
          strokeWidth="4.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity="0.82"
        />
        {arrowHead(
          oxyPts[oxyPts.length - 2],
          oxyPts[oxyPts.length - 1],
          oxyDx,
          oxyDy,
          red
        )}
        {/* Moving oxygenated blood cell */}
        <g>
          <circle cx={oxyDot.x} cy={oxyDot.y} r="7.5" fill={red} opacity="0.95" stroke={ink} strokeWidth="1.4" />
          <ellipse cx={oxyDot.x - 2} cy={oxyDot.y - 2} rx="2.6" ry="1.6" fill="#fff7ed" opacity="0.65" />
        </g>
      </g>

      {/* Sentence [4]: deoxygenated path note + vessel labels + blue flow arrows */}
      <text
        x="86"
        y="436"
        fontFamily={font}
        fontSize="24"
        fill={blue}
        data-teach-order={17}
        data-teach-kind="write"
        data-teach-weight={7}
        data-teach-sentence={4}
      >
        Deoxygenated: body →
      </text>

      <g data-teach-order={18} data-teach-kind="label" data-teach-weight={7} data-teach-sentence={4}>
        {/* Superior vena cava */}
        <line x1={hx - 154} y1={hy - 108} x2="252" y2="176" stroke={ink} strokeWidth="2" />
        <text
          x="86"
          y="180"
          fontFamily={font}
          fontSize="20"
          fill={ink}
          data-teach-order={18}
          data-teach-kind="label"
          data-teach-weight={7}
          data-teach-sentence={4}
        >
          Superior vena cava
        </text>

        {/* Inferior vena cava */}
        <line x1={hx - 126} y1={hy + 156} x2="252" y2="392" stroke={ink} strokeWidth="2" />
        <text
          x="86"
          y="396"
          fontFamily={font}
          fontSize="20"
          fill={ink}
          data-teach-order={19}
          data-teach-kind="label"
          data-teach-weight={7}
          data-teach-sentence={4}
        >
          Inferior vena cava
        </text>

        {/* Pulmonary artery */}
        <line x1={hx - 116} y1={hy - 112} x2="252" y2="146" stroke={ink} strokeWidth="2" />
        <text
          x="86"
          y="150"
          fontFamily={font}
          fontSize="20"
          fill={ink}
          data-teach-order={20}
          data-teach-kind="label"
          data-teach-weight={7}
          data-teach-sentence={4}
        >
          Pulmonary artery
        </text>
      </g>

      <g data-teach-order={21} data-teach-kind="arrow" data-teach-weight={9} data-teach-sentence={4}>
        <polyline
          points={deoxyPts.join(" ")}
          fill="none"
          stroke={blue}
          strokeWidth="4.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          opacity="0.82"
        />
        {arrowHead(
          deoxyPts[deoxyPts.length - 2],
          deoxyPts[deoxyPts.length - 1],
          deoxyDx,
          deoxyDy,
          blue
        )}
        {/* Moving deoxygenated blood cell */}
        <g>
          <circle cx={deoxyDot.x} cy={deoxyDot.y} r="7.5" fill={blue} opacity="0.95" stroke={ink} strokeWidth="1.4" />
          <ellipse cx={deoxyDot.x - 2} cy={deoxyDot.y - 2} rx="2.6" ry="1.6" fill="#eff6ff" opacity="0.7" />
        </g>
      </g>

      {/* Sentence [5]: return to septum annotation */}
      <text
        x="360"
        y="524"
        fontFamily={font}
        fontSize="22"
        fill={teal}
        data-teach-order={22}
        data-teach-kind="write"
        data-teach-weight={7}
        data-teach-sentence={5}
      >
        Septum separates
      </text>

      <g data-teach-order={23} data-teach-kind="annotate" data-teach-weight={8} data-teach-sentence={5}>
        {/* Leader to septum */}
        <path
          d={`M 520 516 C 540 498, 548 460, ${hx + 10} ${hy + 70}`}
          fill="none"
          stroke={teal}
          strokeWidth="3.2"
          strokeLinecap="round"
        />
        {/* Bracket mark along septum */}
        <path
          d={`M ${hx - 6} ${hy + 8} C ${hx + 6} ${hy + 18}, ${hx + 18} ${hy + 18}, ${hx + 30} ${hy + 8}`}
          fill="none"
          stroke={green}
          strokeWidth="3"
          strokeLinecap="round"
          opacity="0.85"
        />
        {/* Small "no-mixing" gesture: two short opposing arrows on each side of septum (no extra words) */}
        <line x1={hx - 18} y1={hy + 28} x2={hx - 44} y2={hy + 28} stroke={blue} strokeWidth="3" strokeLinecap="round" opacity="0.85" />
        <polygon points={`${hx - 44},${hy + 28} ${hx - 34},${hy + 22} ${hx - 34},${hy + 34}`} fill={blue} opacity="0.85" />
        <line x1={hx + 18} y1={hy + 28} x2={hx + 44} y2={hy + 28} stroke={red} strokeWidth="3" strokeLinecap="round" opacity="0.85" />
        <polygon points={`${hx + 44},${hy + 28} ${hx + 34},${hy + 22} ${hx + 34},${hy + 34}`} fill={red} opacity="0.85" />
      </g>
    </svg>
  );
}
